'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useEffect, useState } from 'react';

import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';

import { PAGE_SIZE, RELEASES, SECTION } from './data';
import { ReleaseEntry, releaseAnchorOf } from './release-entry';

const PRESENCE_TRANSITION: Transition = {
  duration: 0.2,
  ease: [0.23, 1, 0.32, 1],
};

const PRESENCE_VARIANTS: Variants = {
  hidden: { opacity: 0, y: 8 },
  shown: { opacity: 1, y: 0 },
};

const FADE_VARIANTS: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1 },
};

function presenceVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return PRESENCE_VARIANTS;
}

function shownCountLabelOf(shown: number, total: number) {
  if (total === 1) {
    return 'Showing the only release';
  }
  return `Showing ${shown} of ${total} releases`;
}

function nextCountOf(count: number) {
  const next = count + PAGE_SIZE;
  return Math.min(next, RELEASES.length);
}

export default function Changelog01() {
  const [visibleCount, setVisibleCount] = useState(PAGE_SIZE);
  const [focusTargetId, setFocusTargetId] = useState<string | null>(null);
  const shouldReduceMotion = useReducedMotion();
  const presenceVariants = presenceVariantsOf(shouldReduceMotion);
  const visibleReleases = RELEASES.slice(0, visibleCount);
  const hasMore = visibleCount < RELEASES.length;
  const shownCountLabel = shownCountLabelOf(visibleCount, RELEASES.length);

  useEffect(() => {
    if (!focusTargetId) {
      return;
    }
    const target = document.getElementById(focusTargetId);
    target?.focus();
  }, [focusTargetId]);

  function loadMore() {
    const firstNewRelease = RELEASES[visibleCount];
    const nextCount = nextCountOf(visibleCount);
    const anchor = releaseAnchorOf(firstNewRelease.version);
    setVisibleCount(nextCount);
    setFocusTargetId(anchor);
  }

  return (
    <section className='px-4 py-16 sm:px-6 sm:py-24 lg:px-8'>
      <div className='mx-auto flex max-w-4xl flex-col gap-12'>
        <div className='flex flex-col gap-2 md:ps-[12rem]'>
          <h2 className='text-2xl font-semibold text-balance sm:text-3xl'>
            {SECTION.title}
          </h2>
          <p className='text-muted-foreground text-base'>
            {SECTION.description}
          </p>
        </div>
        <AnimatedSize>
          <ol className='flex flex-col gap-14'>
            <AnimatePresence initial={false}>
              {visibleReleases.map((release) => (
                <motion.li
                  key={release.version}
                  variants={presenceVariants}
                  initial='hidden'
                  animate='shown'
                  transition={PRESENCE_TRANSITION}
                >
                  <ReleaseEntry release={release} />
                </motion.li>
              ))}
            </AnimatePresence>
          </ol>
        </AnimatedSize>
        <div className='flex flex-col items-start gap-3 md:ps-[12rem]'>
          <p className='text-muted-foreground text-xs tabular-nums'>
            {shownCountLabel}
          </p>
          {hasMore && (
            <Button variant='outline' onClick={loadMore}>
              Load more releases
            </Button>
          )}
        </div>
      </div>
    </section>
  );
}

import { format, parseISO } from 'date-fns';

import { Chip } from '@/registry/ndeko/ui/chip';

import { type Release, TAG_STYLES } from './data';

const DATE_PATTERN = 'd MMM yyyy';

function readableDateOf(isoDate: string) {
  const parsed = parseISO(isoDate);
  return format(parsed, DATE_PATTERN);
}

export function releaseAnchorOf(version: string) {
  return `changelog-01-release-${version}`;
}

export function ReleaseEntry({ release }: { release: Release }) {
  const readableDate = readableDateOf(release.date);
  const anchor = releaseAnchorOf(release.version);

  return (
    <article
      id={anchor}
      tabIndex={-1}
      aria-labelledby={`${anchor}-title`}
      className='focus-visible:ring-ring/25 grid gap-3 rounded-lg outline-none focus-visible:ring-[3px] md:grid-cols-[10rem_minmax(0,1fr)] md:gap-8'
    >
      <div className='flex items-baseline gap-3 md:flex-col md:gap-1'>
        <time dateTime={release.date} className='text-[13px] font-medium'>
          {readableDate}
        </time>
        <span className='text-muted-foreground text-xs tabular-nums'>
          Version {release.version}
        </span>
      </div>
      <div className='flex flex-col gap-3'>
        <div className='flex flex-col gap-2'>
          <h3
            id={`${anchor}-title`}
            className='text-lg font-semibold text-balance'
          >
            {release.title}
          </h3>
          <ul aria-label='Kind of change' className='flex flex-wrap gap-1.5'>
            {release.tags.map((tag) => {
              const tagStyle = TAG_STYLES[tag];

              return (
                <li key={tag}>
                  <Chip color={tagStyle.color}>{tagStyle.label}</Chip>
                </li>
              );
            })}
          </ul>
        </div>
        <p className='text-muted-foreground max-w-2xl text-sm leading-relaxed text-pretty'>
          {release.summary}
        </p>
        <ul className='flex flex-col gap-1.5 text-[13px]'>
          {release.changes.map((change) => (
            <li key={change} className='flex items-baseline gap-2.5'>
              <span
                aria-hidden='true'
                className='bg-foreground/25 size-1 shrink-0 translate-y-[-0.2em] rounded-full'
              />
              {change}
            </li>
          ))}
        </ul>
      </div>
    </article>
  );
}

export type ChangeTag = 'new' | 'improved' | 'fixed';

export type Release = {
  version: string;
  date: string;
  title: string;
  tags: ChangeTag[];
  summary: string;
  changes: string[];
};

export const TAG_STYLES: Record<ChangeTag, { label: string; color: string }> = {
  new: { label: 'New', color: 'var(--primary)' },
  improved: { label: 'Improved', color: 'var(--info)' },
  fixed: { label: 'Fixed', color: 'var(--success)' },
};

export const SECTION = {
  title: 'Changelog',
  description: 'What changed in Loomboard, newest first',
};

export const PAGE_SIZE = 3;

export const RELEASES: Release[] = [
  {
    version: '4.12',
    date: '2026-10-28',
    title: 'Dependencies on the timeline',
    tags: ['new', 'improved'],
    summary:
      'Link two cards and the second one moves when the first one slips. The timeline draws the link and warns you before a date collides.',
    changes: [
      'Drag from the edge of a bar to another bar to link them',
      'Moving a card shifts every card that depends on it',
      'The board shows a small mark on cards that wait for another',
    ],
  },
  {
    version: '4.11',
    date: '2026-10-14',
    title: 'Quieter notifications',
    tags: ['improved'],
    summary:
      'Notifications about the same card are grouped, and nothing arrives outside the working hours you set in your profile.',
    changes: [
      'One notification per card instead of one per change',
      'Working hours per person, with a catch-up summary in the morning',
    ],
  },
  {
    version: '4.10.2',
    date: '2026-10-03',
    title: 'Fixes for shared boards',
    tags: ['fixed'],
    summary:
      'Guests invited to a single board could see the names of other boards in the search. They now only see the board they were invited to.',
    changes: [
      'Search results respect board access for guests',
      'Archived lanes no longer reappear after a page refresh',
    ],
  },
  {
    version: '4.10',
    date: '2026-09-22',
    title: 'Rules that post to a channel',
    tags: ['new'],
    summary:
      'An automation can now post a message in a team channel when a card reaches a lane, with the card title and its owner.',
    changes: [
      'New action: post in a channel',
      'Pick which card fields appear in the message',
    ],
  },
  {
    version: '4.9',
    date: '2026-09-08',
    title: 'Weekly report by person',
    tags: ['new', 'improved'],
    summary:
      'The weekly report splits the hours by person as well as by board, and exports to CSV with the same columns.',
    changes: [
      'A person filter on every report',
      'CSV export keeps the grouping you see on screen',
    ],
  },
  {
    version: '4.8.1',
    date: '2026-08-25',
    title: 'Keyboard fixes',
    tags: ['fixed'],
    summary:
      'Moving a card with the keyboard skipped empty lanes. Arrow keys now stop on every lane, empty or not.',
    changes: ['Arrow keys stop on empty lanes', 'Escape closes the card panel'],
  },
  {
    version: '4.8',
    date: '2026-08-11',
    title: 'Templates for recurring work',
    tags: ['new'],
    summary:
      'Save a board as a template and start the next sprint, launch or onboarding from it with the lanes and rules already in place.',
    changes: [
      'Save any board as a template',
      'Templates keep lanes, labels and automations',
    ],
  },
  {
    version: '4.7',
    date: '2026-07-28',
    title: 'Faster boards with many cards',
    tags: ['improved'],
    summary:
      'Boards with several hundred cards open and scroll without the delay some teams reported on large launches.',
    changes: [
      'Lanes load the cards you can see first',
      'Dragging stays smooth on long lanes',
    ],
  },
];
